//
//  ProgressionEngine.swift
//  Replog
//
//  The deterministic core of the adaptive trainer: given one lift's logged history,
//  recommend what to do next session — add load, add reps, hold, or deload — with a
//  human-readable reason. Classic double progression: work up the rep range at a fixed
//  weight, add load when the top is reached, back off when the estimated 1RM regresses
//  or plateaus. All math lives here in code; the AI model never prescribes numbers.
//

import Foundation

/// What the trainer recommends for the next session of a lift.
enum ProgressionAction: String, Codable, CaseIterable, Sendable {
    case increaseLoad, increaseReps, hold, deload

    var displayName: String {
        switch self {
        case .increaseLoad: return "Add weight"
        case .increaseReps: return "Add a rep"
        case .hold:         return "Repeat"
        case .deload:       return "Deload"
        }
    }
}

/// A concrete next-session prescription for one lift, with the coach's reasoning.
struct ProgressionRecommendation: Equatable, Sendable {
    var exId: String
    var action: ProgressionAction
    /// Suggested working weight, stored in kg like every weight in the app.
    var suggestedWeightKg: Double
    var suggestedReps: Int
    /// One-sentence coach explanation, ready for the log card or a `CoachingLog`.
    var reason: String
}

enum ProgressionEngine {

    /// Deload target as a fraction of the last working weight (~10% off).
    static let deloadFactor = 0.9
    /// Consecutive e1RM *drops* that count as regressing (needs N+1 sessions).
    static let regressionDeltas = 2
    /// Consecutive sessions without an e1RM *improvement* that count as a plateau.
    static let plateauDeltas = 3

    /// The working rep range for double progression, per goal. Brackets the fixed
    /// prescription `PlanGenerator` writes (10 / 13 / 8 reps respectively).
    static func repRange(for goal: Goal) -> ClosedRange<Int> {
        switch goal {
        case .buildMuscle, .recomp: return 8...12
        case .loseWeight:           return 12...15
        case .sport:                return 6...10
        }
    }

    /// Convenience over the primary rule table: rep range from the goal, weight step
    /// and reason formatting from the user's display units.
    static func recommend(exId: String,
                          history: [HistoryEntry],
                          goal: Goal,
                          units: Units = .kg) -> ProgressionRecommendation? {
        recommend(exId: exId,
                  history: history,
                  repRange: repRange(for: goal),
                  weightStepKg: Formulas.weightStepKg(units: units),
                  units: units)
    }

    /// The rule table. History may arrive in any order (sorted by date internally);
    /// pass only entries for `exId`. Returns nil when there is nothing to base a
    /// recommendation on. Rules, first match wins:
    /// 1. Bodyweight lift (top weight 0) → progress by reps only (hold when stalling).
    /// 2. Top of the rep range reached → increase load, rebuild from the bottom.
    /// 3. e1RM dropped `regressionDeltas` sessions in a row → deload ~10%.
    /// 4. No e1RM improvement across `plateauDeltas` sessions → deload ~10%.
    /// 5. Latest session dipped (single off day, not yet a trend) → hold.
    /// 6. Otherwise → add a rep (double progression).
    static func recommend(exId: String,
                          history: [HistoryEntry],
                          repRange: ClosedRange<Int>,
                          weightStepKg: Double = 2.5,
                          units: Units = .kg) -> ProgressionRecommendation? {
        let sorted = history.sorted { $0.date < $1.date }
        guard let last = sorted.last else { return nil }

        // Session-over-session e1RM deltas, oldest → newest.
        let series = sorted.map(\.e1rm)
        let deltas = zip(series.dropFirst(), series).map { $0 - $1 }
        let regressing = deltas.count >= regressionDeltas
            && deltas.suffix(regressionDeltas).allSatisfy { $0 < 0 }
        let plateaued = deltas.count >= plateauDeltas
            && deltas.suffix(plateauDeltas).allSatisfy { $0 <= 0 }

        let weight = { (kg: Double) in Formulas.formatWeight(kg: kg, units: units) }

        // Rule 1 — bodyweight: reps are the only lever, so the range top doesn't cap them.
        // e1RM is weight-based (always 0 here), so the stall signal comes from top reps.
        if last.topW == 0 {
            let repSeries = sorted.map(\.topR)
            let repDeltas = zip(repSeries.dropFirst(), repSeries).map { $0 - $1 }
            let repsRegressing = repDeltas.count >= regressionDeltas
                && repDeltas.suffix(regressionDeltas).allSatisfy { $0 < 0 }
            let repsPlateaued = repDeltas.count >= plateauDeltas
                && repDeltas.suffix(plateauDeltas).allSatisfy { $0 <= 0 }
            if repsRegressing || repsPlateaued {
                return ProgressionRecommendation(
                    exId: exId, action: .hold,
                    suggestedWeightKg: 0, suggestedReps: last.topR,
                    reason: "Progress has stalled — repeat \(last.topR) reps and focus on quality.")
            }
            return ProgressionRecommendation(
                exId: exId, action: .increaseReps,
                suggestedWeightKg: 0, suggestedReps: last.topR + 1,
                reason: "Add a rep — aim for \(last.topR + 1) next time.")
        }

        // Rule 2 — range top reached: add load, rebuild reps from the bottom.
        if last.topR >= repRange.upperBound {
            let next = last.topW + weightStepKg
            return ProgressionRecommendation(
                exId: exId, action: .increaseLoad,
                suggestedWeightKg: next, suggestedReps: repRange.lowerBound,
                reason: "You hit \(last.topR) reps at \(weight(last.topW)) — " +
                        "move up to \(weight(next)) and rebuild from \(repRange.lowerBound) reps.")
        }

        // Rules 3 & 4 — regression / plateau: take ~10% off and rebuild.
        if regressing || plateaued {
            let next = deloadWeight(fromKg: last.topW, stepKg: weightStepKg)
            let why = regressing
                ? "Est. 1RM has dropped \(regressionDeltas + 1) sessions in a row"
                : "No progress across your last \(plateauDeltas + 1) sessions"
            return ProgressionRecommendation(
                exId: exId, action: .deload,
                suggestedWeightKg: next, suggestedReps: repRange.lowerBound,
                reason: "\(why) — deload to \(weight(next)) and rebuild.")
        }

        // Rule 5 — a single down session is noise, not a trend: repeat and consolidate.
        if let lastDelta = deltas.last, lastDelta < 0 {
            let reps = min(max(last.topR, repRange.lowerBound), repRange.upperBound)
            return ProgressionRecommendation(
                exId: exId, action: .hold,
                suggestedWeightKg: last.topW, suggestedReps: reps,
                reason: "Last session dipped — repeat \(weight(last.topW)) × \(reps) and consolidate.")
        }

        // Rule 6 — double progression: same weight, one more rep (never below the range floor).
        let reps = max(min(last.topR + 1, repRange.upperBound), repRange.lowerBound)
        return ProgressionRecommendation(
            exId: exId, action: .increaseReps,
            suggestedWeightKg: last.topW, suggestedReps: reps,
            reason: "Progressing well — aim for \(weight(last.topW)) × \(reps).")
    }

    /// ~10% off the working weight, snapped to the stepper increment, always strictly
    /// below the current weight (floored at 0).
    static func deloadWeight(fromKg kg: Double, stepKg: Double) -> Double {
        guard kg > 0 else { return 0 }
        let target = kg * deloadFactor
        guard stepKg > 0 else { return target }
        var snapped = (target / stepKg).rounded() * stepKg
        if snapped >= kg { snapped -= stepKg }
        return max(0, snapped)
    }
}

//
//  Coaching.swift
//  Replog
//
//  The trainer's durable memory. A `CoachingLog` is a dated, typed note the on-device
//  coach writes to itself — a progression recommendation, a detected plateau, a
//  bodyweight check-in, a published report — so it can "remember" context across weeks
//  and feed later reasoning (progression engine, weekly/monthly reports).
//
//  Like `HistoryEntry`, a log is a flat, queryable record: it references the catalog by
//  `exId` and a plan by `planId` (UUIDs, not relationships — matching `ActiveSession.workoutId`),
//  so the memory OUTLIVES the plan or exercise it once concerned. Structured detail rides
//  in a JSON payload, decoded on demand (the `HistoryEntry.sets` pattern).
//

import Foundation
import SwiftData

/// What a `CoachingLog` records. Drives filtering, iconography, and report grouping.
enum CoachingKind: String, Codable, CaseIterable, Identifiable, Sendable {
    /// A free-form coaching note.
    case note
    /// A load/rep recommendation for a specific lift (from the progression engine).
    case progression
    /// A detected stall across sessions.
    case plateau
    /// A recommended deload / back-off week.
    case deload
    /// A bodyweight check-in observation.
    case bodyweight
    /// A published weekly summary.
    case weeklyReport
    /// A published monthly rollup.
    case monthlyReport
    /// The coach adjusted the plan (split/volume/exercise choice).
    case planAdjustment

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .note:          return "Note"
        case .progression:   return "Progression"
        case .plateau:       return "Plateau"
        case .deload:        return "Deload"
        case .bodyweight:    return "Bodyweight"
        case .weeklyReport:  return "Weekly report"
        case .monthlyReport: return "Monthly report"
        case .planAdjustment: return "Plan adjustment"
        }
    }
}

/// Structured detail for a `CoachingLog`, kept flexible so each `CoachingKind` can carry
/// only what it needs. Numeric facts (weights, e1RM, trend %, bodyweight) go in `metrics`;
/// short labels (recommended action verbs, muscle names) go in `tags`.
// Nonisolated: a pure value type whose Codable conformance must be usable inside the
// nonisolated JSONDecoder/JSONEncoder generics (the custom `init(from:)` would otherwise
// inherit the module's default MainActor isolation).
nonisolated struct CoachingPayload: Codable, Hashable, Sendable {
    /// Named numeric facts, e.g. `["fromWeightKg": 60, "toWeightKg": 62.5, "trendPct": 4.1]`.
    var metrics: [String: Double]
    /// Short labels, e.g. `["increaseLoad"]` or `["chest", "triceps"]`.
    var tags: [String]

    init(metrics: [String: Double] = [:], tags: [String] = []) {
        self.metrics = metrics
        self.tags = tags
    }

    /// Lenient decoding so a bare `{}` (the model's default `payloadJSON`) and forward-compatible
    /// payloads that omit a field decode to sensible empties instead of throwing.
    init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.metrics = try c.decodeIfPresent([String: Double].self, forKey: .metrics) ?? [:]
        self.tags = try c.decodeIfPresent([String].self, forKey: .tags) ?? []
    }

    /// Convenience metric accessor (nil when absent).
    subscript(metric key: String) -> Double? { metrics[key] }
}

@Model
final class CoachingLog {
    var id: UUID = UUID()
    var date: Date = Date()
    /// Stored as `CoachingKind.rawValue`; use `kind` for typed access.
    var kindRaw: String = CoachingKind.note.rawValue
    /// Human-readable one-liner (rendered in reports / a future coaching feed).
    var summary: String = ""
    /// The exercise this log concerns (`Exercise.id` in the static catalog), if any.
    var exId: String?
    /// The plan this log concerns, if any. A plain id reference (not a relationship) so the
    /// memory survives the plan's deletion.
    var planId: UUID?
    /// JSON-encoded `CoachingPayload` of structured detail.
    var payloadJSON: String = "{}"

    init(
        kind: CoachingKind,
        summary: String,
        date: Date = Date(),
        exId: String? = nil,
        planId: UUID? = nil,
        payload: CoachingPayload = CoachingPayload()
    ) {
        self.kindRaw = kind.rawValue
        self.summary = summary
        self.date = date
        self.exId = exId
        self.planId = planId
        self.payload = payload
    }

    var kind: CoachingKind {
        get { CoachingKind(rawValue: kindRaw) ?? .note }
        set { kindRaw = newValue.rawValue }
    }

    /// Decoded structured payload.
    var payload: CoachingPayload {
        get { (try? JSONDecoder().decode(CoachingPayload.self, from: Data(payloadJSON.utf8))) ?? CoachingPayload() }
        set { payloadJSON = String(data: (try? JSONEncoder().encode(newValue)) ?? Data("{}".utf8), encoding: .utf8) ?? "{}" }
    }
}

//
//  SessionBuilder.swift
//  Replog
//
//  Creates a live ActiveSession from a Workout's prescribed sets, pre-filling each
//  set with the "previous" weight/reps from the same set index last session and
//  attaching the ProgressionEngine's next-session suggestion per exercise.
//

import Foundation
import SwiftData

@MainActor
enum SessionBuilder {

    /// Builds and inserts an ActiveSession for `workout`. The caller saves the context.
    @discardableResult
    static func start(workout: Workout, into context: ModelContext) -> ActiveSession {
        let planName = workout.plan?.name ?? ""
        let session = ActiveSession(workoutId: workout.id, name: workout.name, planName: planName)
        context.insert(session)

        let goal = context.userProfile().goal
        let units = context.appSettings().units

        for (exIndex, item) in workout.orderedItems.enumerated() {
            let sessionExercise = SessionExercise(exId: item.exId, order: exIndex)
            sessionExercise.restSeconds = item.restSeconds
            sessionExercise.session = session
            context.insert(sessionExercise)

            let history = context.history(forExercise: item.exId)
            let previous = history.last
            sessionExercise.suggestion = ProgressionEngine.recommend(
                exId: item.exId, history: history, goal: goal, units: units)

            for (setIndex, template) in item.orderedSets.enumerated() {
                let prev = previous?.sets[safe: setIndex]
                let logged = LoggedSet(
                    weightKg: template.weightKg,
                    reps: template.reps,
                    rpe: template.rpe,
                    prevWeight: prev?.w,
                    prevReps: prev?.r,
                    order: setIndex
                )
                logged.exercise = sessionExercise
                context.insert(logged)
            }
        }
        return session
    }
}

extension Array {
    /// Safe indexing that returns nil out of bounds.
    subscript(safe index: Int) -> Element? {
        indices.contains(index) ? self[index] : nil
    }
}

//
//  SessionFinisher.swift
//  Replog
//
//  Finishing a workout: write each exercise's top set to History, bump the streak,
//  mark today complete on the calendar, then remove the live session.
//

import Foundation
import SwiftData

@MainActor
enum SessionFinisher {

    /// Result of finishing, useful for tests/UI feedback.
    struct Summary: Equatable {
        var exercisesLogged: Int
        var newStreak: Int
        var weekStreak: Int
        /// Whether the workout was fully completed (and therefore counted toward streaks).
        var countedAsComplete: Bool
    }

    /// Persists history for every exercise with at least one completed set. Only a *fully
    /// completed* workout counts toward the streaks and the lifetime total: a partial finish
    /// still saves progress (history) but does not mark the scheduled day done, so the
    /// schedule-aware streak can break. Always recomputes both streaks, then deletes the session.
    @discardableResult
    static func finish(_ session: ActiveSession, profile: UserProfile,
                       context: ModelContext, date: Date = Date()) -> Summary {
        let isComplete = session.isComplete

        var logged = 0
        for exercise in session.exercises {
            let doneSets = exercise.sets.filter(\.done)
            guard !doneSets.isEmpty else { continue }
            let top = doneSets.max {
                Formulas.e1rm(kg: $0.weightKg, reps: $0.reps) < Formulas.e1rm(kg: $1.weightKg, reps: $1.reps)
            }!
            let entry = HistoryEntry(
                exId: exercise.exId,
                date: date,
                topW: top.weightKg,
                topR: top.reps,
                e1rm: Formulas.e1rmRounded(kg: top.weightKg, reps: top.reps),
                sets: doneSets.sorted { $0.order < $1.order }.map { RecordedSet(w: $0.weightKg, r: $0.reps) }
            )
            context.insert(entry)
            logged += 1
        }

        if isComplete {
            profile.totalWorkouts += 1
            profile.doneDates = StreakCalendar.recordingCompletion(date, into: profile.doneDates)
        }
        context.recomputeStreaks(profile: profile, today: date)

        let summary = Summary(
            exercisesLogged: logged,
            newStreak: profile.streak,
            weekStreak: profile.weekStreak,
            countedAsComplete: isComplete
        )
        context.delete(session)
        try? context.save()
        return summary
    }
}

//
//  ReplogStore.swift
//  Replog
//
//  Central SwiftData schema, container factories, and fetch-or-create singletons
//  for UserProfile / AppSettings.
//

import Foundation
import SwiftData

enum ReplogSchema {
    /// All persisted model types.
    static let models: [any PersistentModel.Type] = [
        Plan.self, Workout.self, PlanItem.self, SetTemplate.self,
        ActiveSession.self, SessionExercise.self, LoggedSet.self,
        HistoryEntry.self, UserProfile.self, AppSettings.self,
        CoachingLog.self
    ]

    /// The app's on-disk container.
    /// On a fresh device install `Library/Application Support` may not exist yet, which
    /// makes SwiftData fail to create its store ("Failed to create file; code = 2"). We
    /// create that directory first, then open the store; if the store itself is corrupt
    /// or schema-incompatible (e.g. left over from an older build), we wipe it once and
    /// retry, falling back to in-memory as a last resort so the app always launches.
    @MainActor
    static func container() -> ModelContainer {
        let schema = Schema(models)
        let config = ModelConfiguration(isStoredInMemoryOnly: false)
        let storeURL = config.url

        // Ensure the store's parent directory exists.
        try? FileManager.default.createDirectory(
            at: storeURL.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )

        if let c = try? ModelContainer(for: schema, configurations: config) { return c }

        // Genuine corruption / incompatible schema: remove the store files and retry once.
        for suffix in ["", "-shm", "-wal"] {
            try? FileManager.default.removeItem(at: URL(fileURLWithPath: storeURL.path + suffix))
        }
        if let recovered = try? ModelContainer(for: schema, configurations: config) { return recovered }

        // Last resort so the UI still runs (data won't persist).
        return try! ModelContainer(for: schema, configurations: ModelConfiguration(isStoredInMemoryOnly: true))
    }

    /// An ephemeral container for tests and SwiftUI previews.
    @MainActor
    static func inMemoryContainer() -> ModelContainer {
        let config = ModelConfiguration(isStoredInMemoryOnly: true)
        // Force-try is acceptable here: an in-memory store cannot fail for schema reasons
        // that wouldn't also fail the on-disk store caught at app launch.
        return try! ModelContainer(for: Schema(models), configurations: config)
    }
}

// MARK: - Singleton fetch-or-create

extension ModelContext {
    /// Returns the single UserProfile, creating it on first access.
    func userProfile() -> UserProfile {
        if let existing = (try? fetch(FetchDescriptor<UserProfile>()))?.first {
            return existing
        }
        let profile = UserProfile()
        insert(profile)
        return profile
    }

    /// Returns the single AppSettings row, creating it on first access.
    func appSettings() -> AppSettings {
        if let existing = (try? fetch(FetchDescriptor<AppSettings>()))?.first {
            return existing
        }
        let settings = AppSettings()
        insert(settings)
        return settings
    }

    /// All plans in display order.
    func allPlans() -> [Plan] {
        let descriptor = FetchDescriptor<Plan>(sortBy: [SortDescriptor(\.order)])
        return (try? fetch(descriptor)) ?? []
    }

    /// Recomputes both streaks on `profile` from the current plan schedule + completed days.
    /// Call after finishing a workout or whenever the schedule changes.
    func recomputeStreaks(profile: UserProfile, today: Date = Date()) {
        let scheduled = StreakEngine.scheduledDays(in: allPlans())
        profile.streak = StreakEngine.workoutStreak(
            scheduledDays: scheduled, doneDates: profile.doneDates, today: today)
        profile.weekStreak = StreakEngine.weekStreak(
            scheduledDays: scheduled, doneDates: profile.doneDates, today: today)
    }

    /// History entries for one exercise, oldest first.
    func history(forExercise exId: String) -> [HistoryEntry] {
        let descriptor = FetchDescriptor<HistoryEntry>(
            predicate: #Predicate { $0.exId == exId },
            sortBy: [SortDescriptor(\.date)]
        )
        return (try? fetch(descriptor)) ?? []
    }

    // MARK: - Coaching memory

    /// Records a coaching note into the durable memory and returns the inserted log.
    /// This is the single write path the trainer uses to "remember" something.
    @discardableResult
    func recordCoaching(
        _ kind: CoachingKind,
        summary: String,
        date: Date = Date(),
        exId: String? = nil,
        planId: UUID? = nil,
        payload: CoachingPayload = CoachingPayload()
    ) -> CoachingLog {
        let log = CoachingLog(
            kind: kind, summary: summary, date: date,
            exId: exId, planId: planId, payload: payload
        )
        insert(log)
        return log
    }

    /// Coaching logs, newest first. Optionally filtered to one `kind` and capped to `limit`.
    func coachingLogs(kind: CoachingKind? = nil, limit: Int? = nil) -> [CoachingLog] {
        var descriptor = FetchDescriptor<CoachingLog>(sortBy: [SortDescriptor(\.date, order: .reverse)])
        if let kind {
            let raw = kind.rawValue
            descriptor.predicate = #Predicate { $0.kindRaw == raw }
        }
        if let limit { descriptor.fetchLimit = limit }
        return (try? fetch(descriptor)) ?? []
    }

    /// The most recent coaching log of a given kind, if any.
    func latestCoachingLog(kind: CoachingKind) -> CoachingLog? {
        coachingLogs(kind: kind, limit: 1).first
    }

    /// Coaching logs concerning one exercise, newest first.
    func coachingLogs(forExercise exId: String) -> [CoachingLog] {
        let descriptor = FetchDescriptor<CoachingLog>(
            predicate: #Predicate { $0.exId == exId },
            sortBy: [SortDescriptor(\.date, order: .reverse)]
        )
        return (try? fetch(descriptor)) ?? []
    }
}

